package org.telegram.ui; import android.app.Activity; import android.view.Gravity; import android.widget.LinearLayout; import android.widget.TextView; import org.telegram.messenger.AndroidUtilities; import org.telegram.messenger.CustomEconomyManager; import org.telegram.ui.ActionBar.AlertDialog; import org.telegram.ui.ActionBar.Theme; import org.telegram.ui.Components.EditTextBoldCursor; public class AdminPanelDialog extends AlertDialog { public AdminPanelDialog(Activity activity, int currentAccount) { super(activity, 0); setTitle("Админ-панель"); LinearLayout container = new LinearLayout(activity); container.setOrientation(LinearLayout.VERTICAL); container.setPadding(AndroidUtilities.dp(24), AndroidUtilities.dp(8), AndroidUtilities.dp(24), 0); TextView label = new TextView(activity); label.setText("Выдать Кубки пользователю (текущий аккаунт):"); label.setTextSize(14); container.addView(label); EditTextBoldCursor input = new EditTextBoldCursor(activity); input.setHintText("Количество"); input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER); LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, AndroidUtilities.dp(40)); lp.topMargin = AndroidUtilities.dp(8); container.addView(input, lp); setView(container); setPositiveButton("Начислить", (dialogInterface, i) -> { String text = input.getText().toString(); if (!text.isEmpty()) { int amount = Integer.parseInt(text); CustomEconomyManager.getInstance(currentAccount).addCups(amount); } }); setNegativeButton("Отмена", (dialogInterface, i) -> dialogInterface.dismiss()); } }
